import{_ as a,o as n,c as t,a3 as p}from"./chunks/framework.Dz5Q8p4s.js";const g=JSON.parse('{"title":"LTX-Video: Realtime Video Latent Diffusion","description":"","frontmatter":{"title":"LTX-Video: Realtime Video Latent Diffusion","arxiv":"2501.00103","date":"2024-12-30","authors":"Yoav HaCohen, Nisan Chiprut, Benny Brazowski, Daniel Shalem, Dudu Moshe, Eitan Richardson, Eran Levin, Guy Shiran, Nir Zabari, Ori Gordon, Poriya Panet, Sapir Weissbuch, Victor Kulikov, Yaki Bitterman, Zeev Melumian, Ofir Bibi","categories":"cs.CV","topics":"视频扩散, 高压缩 VAE, 实时生成","outline":[2,2]},"headers":[],"relativePath":"papers/2501.00103.md","filePath":"papers/2501.00103.md","lastUpdated":null}'),e={name:"papers/2501.00103.md"};function l(i,s,m,r,c,h){return n(),t("div",null,[...s[0]||(s[0]=[p('<h1 id="ltx-video-realtime-video-latent-diffusion" tabindex="-1">LTX-Video: Realtime Video Latent Diffusion <a class="header-anchor" href="#ltx-video-realtime-video-latent-diffusion" aria-label="Permalink to &quot;LTX-Video: Realtime Video Latent Diffusion&quot;">​</a></h1><table tabindex="0"><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td><strong>arXiv</strong></td><td><a href="https://arxiv.org/abs/2501.00103" target="_blank" rel="noreferrer">2501.00103</a></td></tr><tr><td><strong>提交日期</strong></td><td>2024-12-30</td></tr><tr><td><strong>作者</strong></td><td>Yoav HaCohen, Nisan Chiprut, Benny Brazowski, Daniel Shalem, Dudu Moshe, Eitan Richardson, Eran Levin, Guy Shiran, Nir Zabari, Ori Gordon, Poriya Panet, Sapir Weissbuch, Victor Kulikov, Yaki Bitterman, Zeev Melumian, Ofir Bibi（Lightricks）</td></tr><tr><td><strong>分类</strong></td><td>cs.CV</td></tr><tr><td><strong>一句话</strong></td><td>把 patchify 从 transformer 入口挪到 VAE 入口做到 1:192 压缩，再让 VAE decoder 顺手承担最后一步去噪，于是 2B 以下的模型能在 H100 上用 2 秒生成 5 秒 768×512 视频。</td></tr></tbody></table><blockquote><p><strong>所属教程</strong>：<a href="/notes/tutorials/autoregressive">自回归视频生成</a></p></blockquote><h2 id="§-1-—-研究问题与重要性" tabindex="-1">§ 1 — 研究问题与重要性 <a class="header-anchor" href="#§-1-—-研究问题与重要性" aria-label="Permalink to &quot;§ 1 — 研究问题与重要性&quot;">​</a></h2><p>视频 diffusion transformer 的训练与推理成本几乎完全由 token 数决定，因为 attention 对 token 数是二次的。当时主流模型（CogVideoX、HunyuanVideo、Movie Gen、PyramidFlow）的做法是让 3D VAE 做 8×8×4 或 8×8×8 的时空下采样、通道从 3 升到 16，得到 1:48 或 1:96 的压缩；然后在 transformer 入口再放一个 patchifier，把 2×2×1 的 latent patch 合成一个 token，最终像素到 token 的比例落在 1:1024 或 1:2048。</p><p>问题在于，patchifier 这一步压掉的信息<strong>并没有被 VAE 学过</strong>。它只是把已经算好的 latent 硬拼在一起，既不减少 latent 空间本身的冗余，也没有任何重建目标去约束这次压缩。作者用 PCA 分析 128 条视频的 latent 通道显示了这一点：训练推进过程中 VAE 自己会学着降低通道间冗余，而事后 patchification 对冗余没有贡献。这意味着现有配方在&quot;压缩&quot;这件事上做了一次免费但低质的加码。</p><p>把这件事做对的价值很直接：压缩率翻倍、像素到 token 比例翻两番，同样质量下的生成速度就能进入&quot;比看还快&quot;的区间，模型也就能跑在消费级显卡上。</p><h2 id="§-2-—-前人工作与不足" tabindex="-1">§ 2 — 前人工作与不足 <a class="header-anchor" href="#§-2-—-前人工作与不足" aria-label="Permalink to &quot;§ 2 — 前人工作与不足&quot;">​</a></h2><p><strong>Movie Gen 与 Sora 一类</strong>已经验证了时空 transformer + 全局 self-attention + 3D VAE 的基本架构，但它们采用的是常规 VAE 设计，空间与时间压缩的平衡并没有被专门优化。更关键的是，高压缩必然丢高频细节，这两家的解法是<strong>再加一个模型</strong>：Movie Gen 在压缩更弱的 latent 空间上跑一个 diffusion upsampler，Sora 则在像素空间上跑一个以 latent 为条件的 upsampler。效果有，但计算与延迟成本很大——Movie Gen 的 upsampler 本身就有 7B 参数。</p><p><strong>Pixel-space post-training</strong>（Zhang et al. 2024）试图在 VAE 解码出的带噪 latent 上加像素级 loss，但整个生成过程仍被限制在压缩 latent 空间内，因此改善有限。</p><p><strong>Deep Compression Autoencoder</strong>（与本工作同期）在 text-to-image 上证明了：更高空间压缩因子 + 更高维 latent（可达 64 通道）的 VAE 配 transformer 更有效。但把这个结论扩到视频有额外困难，因为时间维的冗余结构和空间维不同，而且高压缩下的运动重建极易出现闪烁。</p><p>现有工作的共同缺口是：VAE 和 denoising transformer 被当成两个独立组件分别优化，接口固定为&quot;latent&quot;，于是所有高压缩带来的问题都只能靠在接口外面再堆模型来补。</p><h2 id="§-3-—-重建作者的思考路径" tabindex="-1">§ 3 — 重建作者的思考路径 <a class="header-anchor" href="#§-3-—-重建作者的思考路径" aria-label="Permalink to &quot;§ 3 — 重建作者的思考路径&quot;">​</a></h2><p>第一步是观察到 patchifier 是个可疑设计：既然它做的是压缩，为什么不让它进 VAE、接受重建 loss 的监督？把 patchify 移到 VAE encoder 入口，压缩率就从 1:96 提到 1:192，像素到 token 比例从 1:2048 提到 1:8192。</p><p>第二步是承认代价。1:192 的压缩下，高频细节不是&quot;被压坏了&quot;而是&quot;根本没被存下来&quot;，必须在解码时<strong>生成</strong>出来，而不是重建出来。这就把问题重新定性了：解码器不该是一个确定性的重建网络，它应该是一个生成模型。</p><p>第三步是把这个观察和 rectified flow 的一个现实对上。理论上 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.1076em;">f</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3361em;"><span style="top:-2.55em;margin-left:-0.1076em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，但实际推理步数有限，最后一步输出的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 总带残余不确定性；这份不确定性对 decoder 来说就是分布外输入，压缩率越高、高频信号越多的区域越明显。既然 decoder 迟早要面对带噪 latent，不如干脆把它训练成&quot;接受带噪 latent 与时间步、直接输出干净像素&quot;的网络。这样最后一步去噪在像素空间完成，可以用像素级 loss 监督，而且不需要额外的 upsampling 模块。</p><p>第四步是解决高压缩下 GAN 训练的老问题。传统判别器孤立地看一张图判真假，很难判断一块模糊是景深造成的还是重建造成的。既然任务是重建，判别器完全可以同时看到原图与重建图——把绝对判断换成相对判断。</p><h2 id="§-4-—-核心-intuition" tabindex="-1">§ 4 — 核心 Intuition <a class="header-anchor" href="#§-4-—-核心-intuition" aria-label="Permalink to &quot;§ 4 — 核心 Intuition&quot;">​</a></h2><p>压缩到 1:192 之后，高频细节已经不在 latent 里了，所以解码不是重建问题而是生成问题。既然如此，就让 VAE decoder 兼任 diffusion 的最后一步：它接收带噪 latent 与噪声水平，直接输出像素。这一步的表达力是 latent-to-latent 的 base model 永远拿不到的，因为它跨越了维度，并且受像素级 loss 监督。配合把 patchify 塞进 VAE encoder，整条链路上的每一次压缩都被重建目标约束过，于是极高的压缩率不再以画质为代价。</p><h2 id="§-5-—-具体方法与完整-pipeline" tabindex="-1">§ 5 — 具体方法与完整 Pipeline <a class="header-anchor" href="#§-5-—-具体方法与完整-pipeline" aria-label="Permalink to &quot;§ 5 — 具体方法与完整 Pipeline&quot;">​</a></h2><p>以一条 image-to-video 请求为例：</p><ol><li><strong>条件编码</strong>。文本用 T5 编码，经一个可学习投影层接入。作者对比过 cross-attention 与 MM-DiT，选了 cross-attention（论文说 MM-DiT 在他们的设置里更差）。</li><li><strong>首帧编码</strong>。conditioning 图像用 causal VAE encoder 编成时间维为 1 的 latent。选 causal 而非 non-causal 的理由是：causal VAE 更容易做图像与视频的联合训练，也天然支持首帧条件生成；论文承认 non-causal 更容易训出好重建。</li><li><strong>Per-token timestep</strong>。conditioning token 的 diffusion timestep 设为一个很小的 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7651em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.1514em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">c</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>（可为 0，即完全不加噪），其余 token 设为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">1</span></span></span></span>。训练时的做法是偶尔把首帧 token 的 timestep 设成一个小随机值并按该水平加噪。这样 image-to-video 不需要任何额外参数或特殊 token，也可以条件在视频的任意部分上。</li><li><strong>Transformer 去噪</strong>。1.9B 参数、hidden dim 2048、28 个 block，self + cross attention。相对 PixArt-<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0037em;">α</span></span></span></span> 基线的改动有三处：LayerNorm 换 RMSNorm；对 query/key 做归一化以避免 attention logits 出现极大值（对比过 RMSNorm 与 LayerNorm，RMSNorm 更好）；绝对位置编码换成 RoPE，坐标用&quot;按预设最大分辨率与时长归一化的分数坐标&quot;，空间坐标以像素计、时间坐标以秒计并把原始 FPS 纳入时间嵌入。RoPE 频率用指数递增而非常见的逆指数间隔。</li><li><strong>Denoising decoder 收尾</strong>。跑完约 20 步 latent-to-latent 去噪后，把 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6807em;vertical-align:-0.2501em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3173em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2501em;"><span></span></span></span></span></span></span></span></span></span> 连同 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.7651em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 一起交给 VAE decoder，一次性输出干净像素。decoder 用 adaptive normalization 接收 timestep 条件，训练时的噪声水平范围是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.2</span><span class="mclose">]</span></span></span></span>，对应常见调度器的最后若干步。</li><li><strong>VAE 的训练配方</strong>。最终 loss 是像素 MSE + Video-DWT（对输入与重建各算 8 个 3D 离散小波变换，取 L1）+ LPIPS 感知 loss + Reconstruction GAN。另外两个细节：多层噪声注入（在 decoder 若干层注入噪声，噪声强度按通道学习）用来产生更多样的高频细节；uniform log-variance（全部 latent 通道共享一个预测的 log-variance）用来避免宽 latent 空间下部分通道被 KL loss &quot;牺牲&quot;掉而不参与重建。3D 卷积略优于&quot;2D 空间核 + 1D 时间核&quot;的可分离卷积。</li><li><strong>训练调度</strong>。rectified flow，网络预测速度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span></span></span></span>。timestep 从 log-normal 采样并按 token 数把分布往高噪声区移，同时把 pdf 在 0.5 与 99.9 百分位处截断，防止尾部饿死。多分辨率联合训练：把不同分辨率与时长的样本 resize 到相近 token 数，再用 0%–20% 的随机 token dropping 把 token 数对齐，从而免掉 token packing 与 padding。图像训练被当成&quot;时长为 1&quot;的一种分辨率组合混进来。</li><li><strong>数据</strong>。用成对人工标注（数万对图像，标注哪张更好看）训练一个 Siamese 结构的美学模型；为了让采样的对不至于分布偏移，先用多标签网络给数百万样本打标，只采样共享 top-3 标签之一的对。此外过滤掉运动过小的视频、裁掉黑边，并用内部 captioner 对全部训练数据重新生成描述。</li></ol><h2 id="§-6-—-核心数学推导" tabindex="-1">§ 6 — 核心数学推导 <a class="header-anchor" href="#§-6-—-核心数学推导" aria-label="Permalink to &quot;§ 6 — 核心数学推导&quot;">​</a></h2><p>Rectified flow 的前向过程是线性插值：</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.8095em;vertical-align:-0.1944em;"></span><span class="mord mathnormal">t</span><span class="mord mathnormal">ϵ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:2em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal">ϵ</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∼</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal" style="margin-right:0.1474em;">N</span><span class="mopen">(</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord mathnormal" style="margin-right:0.0785em;">I</span><span class="mclose">)</span></span></span></span></span></p><p>原始 diffusion 让网络预测 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">ϵ</span></span></span></span>，但这个任务在不同 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 上难度极不均衡；改为预测速度 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6667em;vertical-align:-0.0833em;"></span><span class="mord mathnormal">ϵ</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span> 后，推理时每步更新为 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6389em;vertical-align:-0.2083em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3283em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="mbin mtight">−</span><span class="mord mtight">Δ</span><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2083em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.7333em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.0961em;vertical-align:-0.247em;"></span><span class="mord">Δ</span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.0359em;">v</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.8491em;"><span style="top:-2.453em;margin-left:-0.0359em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">t</span></span></span><span style="top:-3.063em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight" style="margin-right:0.0278em;">θ</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.247em;"><span></span></span></span></span></span></span></span></span></span>。</p><p>本文的关键改动在解码端。常规 latent diffusion 的解码是 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathcal" style="margin-right:0.0278em;">D</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，本文改成</p><p class="katex-block"><span class="katex-display"><span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0001em;vertical-align:-0.2501em;"></span><span class="mord mathcal" style="margin-right:0.0278em;">D</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3281em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2501em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord mathcal" style="margin-right:0.0278em;">D</span><span class="mord"><span class="delimsizing size1">(</span></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1.2em;vertical-align:-0.35em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord mathnormal">ϵ</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3117em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mathnormal mtight">i</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mord"><span class="delimsizing size1">)</span></span></span></span></span></span></p><p>要理解它为什么合理，注意 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6833em;"></span><span class="mord mathcal" style="margin-right:0.0278em;">D</span></span></span></span> 在不同维度的空间之间映射，所以<strong>不能</strong>像标准 diffusion 那样被反复迭代。但它可以执行最后一步 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal">x</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1.0001em;vertical-align:-0.2501em;"></span><span class="mord mathcal" style="margin-right:0.0278em;">D</span><span class="mopen">(</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3173em;"><span style="top:-2.357em;margin-left:0em;margin-right:0.0714em;"><span class="pstrut" style="height:2.5em;"></span><span class="sizing reset-size3 size1 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.143em;"><span></span></span></span></span></span></span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.2501em;"><span></span></span></span></span></span></span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord"><span class="mord mathnormal">t</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:0em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">1</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mclose">)</span></span></span></span>，而这一步是 base model 做不到的：latent-to-latent 的去噪被 latent 空间的表达力上限卡住，而 denoising decoder 直接吐像素，并用像素空间的 loss 训练。换句话说，残余不确定性不再是需要被消除的误差，而是被交给一个更有表达力的模块去&quot;补完&quot;的自由度。</p><p>Reconstruction GAN 改的是判别器的输入。传统 GAN 中判别器看到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.4306em;"></span><span class="mord mathnormal">x</span></span></span></span> 或 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6944em;"></span><span class="mord accent"><span class="vlist-t"><span class="vlist-r"><span class="vlist" style="height:0.6944em;"><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="mord mathnormal">x</span></span><span style="top:-3em;"><span class="pstrut" style="height:3em;"></span><span class="accent-body" style="left:-0.2222em;"><span class="mord">^</span></span></span></span></span></span></span></span></span></span> 之一并输出真假；rGAN 把两者拼接后同时给判别器，让它判断哪一个是原始、哪一个是重建。这把一个绝对的密度比估计问题换成了相对比较问题，判别器不再需要独立判断&quot;一块模糊是否合理&quot;，只需判断&quot;哪一块更像原图&quot;。副产品是判别器同时充当了一个鲁棒的重建 loss。</p><h2 id="§-7-—-实验设计与结论" tabindex="-1">§ 7 — 实验设计与结论 <a class="header-anchor" href="#§-7-—-实验设计与结论" aria-label="Permalink to &quot;§ 7 — 实验设计与结论&quot;">​</a></h2><p><strong>问题一：这套压缩配方在同量级上是否可用？</strong> 表 1 给出对照：LTX-Video 1.9B / hidden 2048 / 28 blocks，VAE 输出 128 通道（其余四个模型都是 16），总压缩 1:192（Movie Gen 与 PyramidFlow 1:96、HunyuanVideo 与 CogVideoX 1:48），tokens-to-pixels 1:8192（其余为 1:2048 或 1:1024），且不需要 upsampling 模型（Movie Gen 需要 7B 的 upsampler）。</p><p><strong>问题二：质量上是否被压缩率拖垮？</strong> 做人工评测：1000 条 prompt 做 text-to-video、1000 组图文对做 image-to-video，统一 5 秒、768×512、40 步。20 名参与者盲评随机配对（包括不含 LTX-Video 的配对），可跳过。为验证样本量足够，把参与者分成两组各 10 人，组间胜率差异小于 2%。结果中 LTX-Video 的胜率为 85%（text-to-video）与 91%（image-to-video），三个同量级对手落在 20%–51% 与 20%–47% 区间。</p><p><strong>问题三：denoising decoder 是不是真的有用？</strong> 内部 user study 对照两组：decoder 条件在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.05</span></span></span></span>（执行末步去噪）与 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.0</span></span></span></span>（不去噪）。结论是前者被明显偏好，且在高运动视频上差距最大——那正是强压缩最容易出伪影的场景。</p><p><strong>问题四：rGAN 与 RoPE 频率间隔的选择有据吗？</strong> rGAN 的证据是定性的：1:192 压缩下常规&quot;重建 + GAN&quot;组合在快速运动且细节复杂的帧上重建不一致（作者说单帧未必看得出，播放时才明显），换成 rGAN 后伪影显著减少。RoPE 的证据是定量的：在完全相同的架构、超参与数据下，指数间隔的训练 loss 始终低于逆指数间隔。</p><p><strong>速度</strong>：H100 上 20 步生成 121 帧 768×512 只需 2 秒，即快于实时；这是蒸馏之前的数字。</p><p><strong>论文自陈的限制</strong>：对 prompt 表述敏感，模糊 prompt 结果差；目前只支持约 10 秒以内的短视频；对多视角合成、细粒度编辑这类领域特化任务未做充分测试。</p><h2 id="§-8-—-take-aways" tabindex="-1">§ 8 — Take-aways <a class="header-anchor" href="#§-8-—-take-aways" aria-label="Permalink to &quot;§ 8 — Take-aways&quot;">​</a></h2><p><strong>5 句话版</strong>：LTX-Video 把 patchify 从 transformer 入口移进 VAE encoder，使每一次压缩都受重建 loss 监督，达到 1:192 总压缩与 1:8192 的像素-token 比。高压缩必然丢高频，所以 VAE decoder 被重训成接受带噪 latent 与时间步、直接输出像素的 diffusion 模块，承担最后一步去噪，从而免掉额外的 upsampler。Reconstruction GAN 把判别器的绝对真假判断换成&quot;原图与重建图哪个是原图&quot;的相对判断，显著改善了高压缩下的运动重建。transformer 侧的改动是 RMSNorm、QK 归一化与归一化分数坐标的 RoPE（指数频率间隔）。最终 1.9B 模型在 H100 上 2 秒产出 5 秒 768×512 视频，人工评测胜率 85%（t2v）/ 91%（i2v）。</p><p><strong>3 句话版</strong>：把压缩全部交给受监督的 VAE，把最后一步去噪交给 decoder 在像素空间完成。相对判断式的 rGAN 让 1:192 压缩下的重建稳住。结果是同量级里最快且评测最优的开源视频模型。</p><p><strong>1 句话版</strong>：VAE 与 denoising transformer 不该被当成两个独立组件，把压缩和末步去噪都交给 VAE，就能在不加 upsampler 的前提下把压缩率翻倍。</p><h2 id="§-9-—-最脆弱的假设" tabindex="-1">§ 9 — 最脆弱的假设 <a class="header-anchor" href="#§-9-—-最脆弱的假设" aria-label="Permalink to &quot;§ 9 — 最脆弱的假设&quot;">​</a></h2><p>最脆弱的是：<strong>最后一步残余不确定性所对应的高频细节，可以由一个前馈 decoder 在单步内、仅凭带噪 latent 与标量时间步生成得&quot;足够对&quot;</strong>。整套设计的性价比全押在这里——正因为相信单步够用，才敢把压缩推到 1:192 并砍掉 upsampler。这个假设在实践中可能不成立的地方是：单步前馈无法表达多峰分布，当同一个带噪 latent 对应多种合理的高频实现（快速运动的细纹理、文字、周期性图案）时，decoder 只能输出某种平均，或者依赖多层噪声注入去掷一次骰子，而这次采样并不以时间一致性为条件。</p><p>论文提供的证据是间接且偏弱的：一个内部 user study（<span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.05</span></span></span></span> 优于 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.0</span></span></span></span>）与若干定性图。缺的是逐帧客观指标——比如高频带的功率谱与 ground truth 的匹配、以及跨帧的高频闪烁度量。作者自己也提到 rGAN 那类伪影&quot;单帧未必看得出、播放时才明显&quot;，这恰恰说明单帧指标不足以支撑这个假设，而时间维的指标论文没有给。以上属于基于证据的推断，不是作者的声明。</p><h2 id="§-10-—-最小复现实验" tabindex="-1">§ 10 — 最小复现实验 <a class="header-anchor" href="#§-10-—-最小复现实验" aria-label="Permalink to &quot;§ 10 — 最小复现实验&quot;">​</a></h2><p>只测 VAE，不训 transformer，一周可完成。用公开的 LTX-Video VAE 权重，取一批含高频纹理与快速运动的真实视频（例如水面、树叶、人群、滚动字幕）。对每条视频编码得到 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span></span></span></span>，人工构造 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.5806em;vertical-align:-0.15em;"></span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.2806em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight"><span class="mord mathnormal mtight">t</span></span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">(</span><span class="mord">1</span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">−</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mord mathnormal">t</span><span class="mclose">)</span><span class="mord"><span class="mord mathnormal" style="margin-right:0.044em;">z</span><span class="msupsub"><span class="vlist-t vlist-t2"><span class="vlist-r"><span class="vlist" style="height:0.3011em;"><span style="top:-2.55em;margin-left:-0.044em;margin-right:0.05em;"><span class="pstrut" style="height:2.7em;"></span><span class="sizing reset-size6 size3 mtight"><span class="mord mtight">0</span></span></span></span><span class="vlist-s">​</span></span><span class="vlist-r"><span class="vlist" style="height:0.15em;"><span></span></span></span></span></span></span><span class="mspace" style="margin-right:0.2222em;"></span><span class="mbin">+</span><span class="mspace" style="margin-right:0.2222em;"></span></span><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mord mathnormal">ϵ</span></span></span></span>，在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6542em;vertical-align:-0.0391em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.05</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.2</span><span class="mclose">}</span></span></span></span> 上各解码一次。测量三件事：与原视频的 LPIPS；高频带（DWT 高频子带）能量与 ground truth 的比值；相邻帧高频子带能量的逐帧方差（闪烁代理指标）。若 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.05</span></span></span></span> 相对 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0</span></span></span></span> 在 LPIPS 与高频能量上更接近 ground truth，就复现了论文的 user study 结论；若同时闪烁指标反而变大，则说明单步生成买到了细节但付出了时间一致性的代价，这是论文没有报告的维度。再用同一批视频、固定 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">=</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:0.6444em;"></span><span class="mord">0.05</span></span></span></span> 但换不同随机种子解码多次，比较高频细节的方差，可以直接量化&quot;多峰分布被塌成平均值&quot;的程度。</p><h2 id="§-11-—-最强反例设计" tabindex="-1">§ 11 — 最强反例设计 <a class="header-anchor" href="#§-11-—-最强反例设计" aria-label="Permalink to &quot;§ 11 — 最强反例设计&quot;">​</a></h2><p>替代解释：LTX-Video 的胜率优势可能主要来自数据配方与 caption 质量，而非架构。论文明确说全部训练数据都用内部 captioner 重新描述过，并用成对标注训练的美学模型做了强过滤，而人工评测的判据里包含&quot;prompt adherence&quot;——这一项对 caption 分布与评测 prompt 分布的匹配度极其敏感。三个对照模型都没有经过这样的重标注。</p><p>据此设计的攻击实验：把 LTX-Video 的 VAE 换成一个常规 1:96 压缩的 VAE，其余训练数据、caption、超参、总训练 FLOPs 全部保持不变，重训一个同参数量模型，再做同样的盲评。若两者胜率接近，那么&quot;1:192 压缩 + denoising decoder&quot;就只是一个<strong>速度</strong>优化而非质量优化，论文标题里那句&quot;outperforming all existing models of similar scale&quot;需要归因到数据侧。一个更便宜的近似版本是：把三个 baseline 的评测 prompt 先用 LTX-Video 的 captioner 风格重写一遍再评测，看胜率差距缩小多少。</p><h2 id="§-12-—-follow-up-research-idea" tabindex="-1">§ 12 — Follow-up Research Idea <a class="header-anchor" href="#§-12-—-follow-up-research-idea" aria-label="Permalink to &quot;§ 12 — Follow-up Research Idea&quot;">​</a></h2><p><strong>驱动局限</strong>：本文把&quot;最后一步去噪&quot;从 latent 空间搬到了像素空间，但仍然是<strong>固定的一步</strong>，且噪声水平范围被写死在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.2</span><span class="mclose">]</span></span></span></span>。这等于假定 latent-to-latent 与 latent-to-pixel 之间存在一个全局最优的切换点，与内容无关。而论文自己的证据表明切换点的收益高度依赖内容——高运动视频受益最大。</p><p><strong>新 framing</strong>：把&quot;在哪一步从 latent 域切到像素域&quot;当成一个逐样本、甚至逐区域的决策，而不是全局常数。可借鉴的相邻领域工具有两个：视频编码里的 rate-distortion 优化（按块分配码率的成熟框架），以及 diffusion 蒸馏里关于&quot;哪些时间步真正携带信息&quot;的分析。具体设想是训练一族条件在 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6542em;vertical-align:-0.0391em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">[</span><span class="mord">0</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.5</span><span class="mclose">]</span></span></span></span> 上的 denoising decoder，再学一个轻量的切换策略，用 base model 在若干候选 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 上的速度预测方差作为&quot;该样本残余不确定性&quot;的估计来决定切换点。</p><p><strong>第一个实验</strong>：先验证&quot;最优切换点确实随内容变化&quot;这一前提。用扩展噪声范围重训 decoder，然后在一批分层的测试视频（按光流幅度分成低/中/高三档）上，对每条视频扫描 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6542em;vertical-align:-0.0391em;"></span><span class="mord mathnormal">t</span><span class="mspace" style="margin-right:0.2778em;"></span><span class="mrel">∈</span><span class="mspace" style="margin-right:0.2778em;"></span></span><span class="base"><span class="strut" style="height:1em;vertical-align:-0.25em;"></span><span class="mopen">{</span><span class="mord">0.05</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.1</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.2</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.3</span><span class="mpunct">,</span><span class="mspace" style="margin-right:0.1667em;"></span><span class="mord">0.5</span><span class="mclose">}</span></span></span></span> 并记录 LPIPS 最优点。若最优 <span class="katex"><span class="katex-html" aria-hidden="true"><span class="base"><span class="strut" style="height:0.6151em;"></span><span class="mord mathnormal">t</span></span></span></span> 与光流幅度呈显著相关，就说明固定切换点在低运动样本上浪费了 transformer 的步数、在高运动样本上又切得太晚；随后即可用总步数预算固定的自适应策略去争取净收益。</p>',53)])])}const d=a(e,[["render",l]]);export{g as __pageData,d as default};
